function print_aliases(){
printf "Your aliases were created successfully. You can now use the following commands when connecting to a target via SIA:\n"
zsp_params=$1
sta_params=$2
shift
shift
echo "For Zero Standing Privileges access, use:"
for alias in "$@"
do
echo "$alias" "$zsp_params"
done
echo "\nFor Vaulted credentials access, use:"
for alias in "$@"
do
echo "$alias" "$sta_params"
done
}
function sanitize_user_input_for_filename(){
file_name=$(echo "$1" | sed -r 's/[/\\:?<>|*]//g')
echo $file_name
}
function setup_alias() {
ALIAS="$1"
FUNCTION_NAME="$2"
COMMAND="$3"
if [ -f "$HOME/.zshrc" ]
then
setup_alias_internal "$ALIAS" "$FUNCTION_NAME" "$COMMAND" "$HOME/.zshrc"
fi
setup_alias_internal "$ALIAS" "$FUNCTION_NAME" "$COMMAND" "$HOME/.bashrc"
}
function setup_alias_internal() {
ALIAS="$1"
FUNCTION_NAME="$2"
COMMAND="$3"
RC="$4"
if [[ $(grep -c "$ALIAS=" "$RC") -gt 0 ]]; then
sed -i.bak "/alias $ALIAS/d" "$RC"
sed -i.bak "/^$FUNCTION_NAME/,/^}/d" "$RC"
fi
if [[ $(grep -c "sanitize_user_input_for_filename" "$RC") -eq 0 ]]; then
echo "sanitize_user_input_for_filename(){
file_name=$(echo "\$1" | sed -r 's/[/\\:?<>|*]//g')
echo \$file_name
}" >> "$RC"
fi
echo "$COMMAND" >> "$RC"
echo alias "$ALIAS"=\""$FUNCTION_NAME"\" >> "$RC"
}
function get_user_input() {
MESSAGE="$1"
USER_INPUT=""
while [[ -z "$USER_INPUT" ]]
do
if [ -n "$BASH_VERSION" ]; then
read -p "$MESSAGE " USER_INPUT;
else
read -r "USER_INPUT?$MESSAGE "
fi
done
echo "$USER_INPUT"
}
function set_aliases_without_username(){
ssh_gw_address="$1"
tenant="$2"
key_path="$3"
setup_alias cybr-ssh f-ssh "f-ssh() {
counter="'"${1//[^@]}" && counter="${#counter}"'"
if [[ "\$counter" -eq 2 ]]
then
IFS="'"@"'" read -r USER_NAME LOGIN_PREFIX TARGET_ID <<< "'"$1"'"
file_name=$(sanitize_user_input_for_filename "$tenant"_"\$USER_NAME"@"\$LOGIN_PREFIX");
KEY_PATH=$key_path/"\$file_name"
if [ -f "\$KEY_PATH" ]
then
ssh -i "\$KEY_PATH" "\$USER_NAME"@"\$LOGIN_PREFIX"#$tenant@"\$TARGET_ID"@${ssh_gw_address}
else
ssh "\$USER_NAME"@"\$LOGIN_PREFIX"#$tenant@"\$TARGET_ID"@${ssh_gw_address}
fi
else
if [[ "\$counter" -eq 3 ]]
then
IFS="'"@"'" read -r USER_NAME LOGIN_PREFIX TARGET_USER TARGET_ID <<< "'"$1"'"
file_name=$(sanitize_user_input_for_filename "$tenant"_"\$USER_NAME"@"\$LOGIN_PREFIX");
KEY_PATH=$key_path/"\$file_name"
if [ -f "\$KEY_PATH" ]
then
ssh -i "\$KEY_PATH" "\$USER_NAME"@"\$LOGIN_PREFIX"#$tenant@"\$TARGET_USER"@"\$TARGET_ID"@${ssh_gw_address}
else
ssh "\$USER_NAME"@"\$LOGIN_PREFIX"#$tenant@"\$TARGET_USER"@"\$TARGET_ID"@${ssh_gw_address}
fi
else
echo 'Bad input. Use this syntax:\nFor Zero Standing Privileges access, use:\ncybr-ssh <username>@<login_prefix>@<target_address>\n\nFor Vaulted credentials access, use:\ncybr-ssh <username>@<login_prefix>@<target_user>@<target_address>'
fi
fi
}"
setup_alias cybr-login f-login "f-login() {
full_user_name="\$1"
key_path="\$2"
if [[ -z "\$full_user_name" ]]
then
echo 'Bad input. Use this syntax:\nFor Zero Standing Privileges access, use:\ncybr-sso <username>@<login_prefix>@<target_address>\n\nFor Vaulted credentials access, use:\ncybr-sso <username>@<login_prefix>@<target_user>@<target_address>'
else
sftp -i "\$key_path" "\$full_user_name"#${tenant}@key@${ssh_gw_address}:/key "\$key_path"
fi
}"
setup_alias cybr-sso f-sso "f-sso() {
counter="'"${1//[^@]}" && counter="${#counter}"'"
if [[ "\$counter" -eq 2 ]]
then
IFS="'"@"'" read -r USER_NAME LOGIN_PREFIX TARGET_ID <<< "'"$1"'"
file_name=$(sanitize_user_input_for_filename "$tenant"_"\$USER_NAME"@"\$LOGIN_PREFIX");
KEY_PATH=$key_path/"\$file_name"
cybr-login "\$USER_NAME"@"\$LOGIN_PREFIX" "\$KEY_PATH"
cybr-ssh "\$1"
else
if [[ "\$counter" -eq 3 ]]
then
IFS="'"@"'" read -r USER_NAME LOGIN_PREFIX TARGET_ID <<< "'"$1"'"
file_name=$(sanitize_user_input_for_filename "$tenant"_"\$USER_NAME"@"\$LOGIN_PREFIX");
KEY_PATH=$key_path/"\$file_name"
cybr-login "\$USER_NAME"@"\$LOGIN_PREFIX" "\$KEY_PATH"
cybr-ssh "\$1"
else
echo 'Bad input. Use this syntax:\nFor Zero Standing Privileges access, use:\ncybr-sso <username>@<login_prefix>@<target_address>\n\nFor Vaulted credentials access, use:\ncybr-sso <username>@<login_prefix>@<target_user>@<target_address>'
fi
fi
}"
}
