$ALIAS_CREATED = "Your aliases were created successfully. You can now use the following commands when connecting to a target via SIA:"
$ALIAS_CREATED_ZSP = "For Zero Standing Privileges access, use:"
$ALIAS_CREATED_STA = "For Vaulted credentials access, use:"
$BAD_INPUT = "Bad input. Use this syntax:"
$ENTER_PATH = "Enter the path where the key will be saved, or leave empty to use the default path"
function Write-CYBRAliases {
Param (
[string]$zspParams,
[string]$staParams,
[string[]]$aliases
)
Write-Host -ForegroundColor Green "`n$ALIAS_CREATED"
Write-Host -ForegroundColor Cyan "`n$ALIAS_CREATED_ZSP`n"
foreach ($alias in $aliases) {
Write-Host "$alias" "$zspParams"
}
Write-Host -ForegroundColor Cyan "`n$ALIAS_CREATED_STA`n"
foreach ($alias in $aliases) {
Write-Host "$alias" "$staParams"
}
}
function Set-CYBRAlias {
Param (
[string]$aliasName,
[string]$functionName,
[string]$codeBlock
)
if (Get-Content -Path $Profile.CurrentUserAllHosts | Select-String -Pattern ('^function\s{0}\s' -f $functionName)) {
$currProfile = Get-Content -Path $Profile.CurrentUserAllHosts -Raw
$currProfile = ($currProfile -replace "(?m)^function\s$functionName(.*\n)*?^}") -replace "(?m)^\s*$"
Set-Content -Path $Profile.CurrentUserAllhosts -Value $currProfile -Force
$currProfile = $null
}
Add-Content -Path $Profile.CurrentUserAllHosts -Value $codeBlock > $null
if (Get-Content -Path $Profile.CurrentUserAllhosts | Select-String -Pattern ('^New-Alias\s-Name\s"{0}"' -f $aliasName)) {
$currProfile = Get-Content -Path $Profile.CurrentUserAllHosts -Raw
$currProfile = ($currProfile -replace ('(?m)^New-Alias\s-Name\s"{0}"\s-Value\s"{1}".*$' -f $aliasName, $functionName)) -replace "(?m)^\s*$"
Set-Content -Path $Profile.CurrentUserAllhosts -Value $currProfile -Force
$currProfile = $null
}
Add-Content -Path $Profile.CurrentUserAllHosts -Value ('New-Alias -Name "{0}" -Value "{1}" -Force -ErrorAction SilentlyContinue' -f $aliasName, $functionName)
}
