function Import-CYBRAliases {
do {
$tenant = Read-Host -Prompt "Enter your CyberArk tenant name (subdomain)"
if (!$tenant) {
Clear-Host
}
}
while (!$tenant)
$sshGWAddress = ($tenant -replace ".cyberark.cloud") + ".ssh.cyberark.cloud"
$user = Read-Host -Prompt "Enter your full username <username>@<login_suffix>, or leave empty so the username is not saved and authentication of different identities is enabled"
$keyFileName = ($tenant + "_" + $user) -replace "[/\\:?<>|*]"
$zspParams = ""
$staParams = ""
if ([string]::IsNullOrEmpty($user)) {
$keyPath = Read-Host -Prompt "$ENTER_PATH [$($env:USERPROFILE)\.ssh\<tenant_name>_<username>@<login_suffix>]"
if ([string]::IsNullOrEmpty($keyPath)) {
if (!$(Test-Path -Path "$($env:USERPROFILE)\.ssh")) {
New-Item -ItemType Directory -Path "$($env:USERPROFILE)\.ssh" > $null
}
$keypath = "$($env:USERPROFILE)\.ssh"
}
else {
if (!$(Test-Path -Path $keyPath)) {
New-Item -ItemType Directory -Path $keyPath > $null
}
}
Set-CYBRAliasesWithoutUsername -sshGWAddress $sshGWAddress -tenant $tenant -keyPath $keyPath
$zspParams = "<username>@<login_suffix>@<target_address>"
$staParams = "<username>@<login_suffix>@<target_user>@<target_address>"
}
else {
$keyPath = Read-Host -Prompt "$ENTER_PATH [$($env:USERPROFILE)\.ssh\$keyFileName]"
if ([string]::IsNullOrEmpty($keyPath)) {
if (!$(Test-Path -Path "$($env:USERPROFILE)\.ssh")) {
New-Item -ItemType Directory -Path "$($env:USERPROFILE)\.ssh" -Force > $null
}
$keypath = "$($env:USERPROFILE)\.ssh"
}
else {
if (!$(Test-Path -Path $keyPath)) {
New-Item -ItemType Directory -Path $keyPath > $null
}
}
Set-CYBRAliasesWithUsername -user $user -keyPath $keyPath -keyFileName $keyFileName -sshGWAddress $sshGWAddress -tenant $tenant
$zspParams="<target_address>"
$staParams="<target_user>@<target_address>"
}
Write-CYBRAliases -zspParams $zspParams -staParams $staParams -aliases @("cybr-ssh", "cybr-sso")
}
function CheckPrerequisites {
if (!(Get-Command -Name "ssh" -CommandType Application -ErrorAction SilentlyContinue) -or !(Get-Command -Name "sftp" -CommandType Application -ErrorAction SilentlyContinue)) {
Write-Host -ForegroundColor Cyan "You do not have the OpenSSH clients for ssh or sftp installed. Please install these first and try again."
Write-Host -NoNewline -ForegroundColor Yellow "`nPress any key to exit..."
$Host.UI.RawUI.ReadKey('NoEcho,IncludeKeyDown') > $null
exit
}
}
function BuildUserProfile {
if (!$(Test-Path -Path $Profile.CurrentUserAllHosts)) {
New-Item -ItemType File -Path $Profile.CurrentUserAllHosts -Force > $null
}
elseif (!$(Test-Path -Path "$($Profile.CurrentUserAllHosts).bak")) {
Copy-Item -Path $Profile.CurrentUserAllHosts -Destination "$($Profile.CurrentUserAllHosts).bak" > $null
}
}
function PostNotify {
Write-Host -ForegroundColor Magenta "`nClose and reopen any existing shells for these changes to take effect."
Write-Host -NoNewline -ForegroundColor Yellow "`nPress any key to exit..."
$Host.UI.RawUI.ReadKey('NoEcho,IncludeKeyDown') > $null
}
### Entry Point ###
Clear-Host
CheckPrerequisites
BuildUserProfile
Import-CYBRAliases
PostNotify
Clear-Host

IAM role for an Amazon Kendra retriever
When you use an Amazon Kendra index as a retriever, you must provide Amazon Q Business with an IAM role with permissions to access Amazon Kendra.
You must also provide a trust policy that allows Amazon Q to assume the role. The
following are the policies that must be provided.
To allow Amazon Q to access your Amazon Kendra index, use the
following policy:
- JSON
-
-
{
"Version":"2012-10-17",
"Statement": [
{
"Sid": "KendraRetrieveAccess",
"Effect": "Allow",
"Action": [
"kendra:Retrieve",
"kendra:DescribeIndex"
],
"Resource": "arn:aws:kendra:us-east-1:111122223333:index/example-index-id
"
}
]
}
To allow Amazon Q to assume a role, use the following trust
policy:
- JSON
-
-
{
"Version":"2012-10-17",
"Statement": [
{
"Sid": "AmazonQKendraAccessPermission",
"Effect": "Allow",
"Principal": {
"Service": "qbusiness.amazonaws.com"
},
"Action": "sts:AssumeRole",
"Condition": {
"StringEquals": {
"aws:SourceAccount": "111122223333"
},
"ArnEquals": {
"aws:SourceArn": "arn:aws:qbusiness:us-east-1:111122223333:application/application-id
"
}
}
}
]
}
